test('issueInvoice assigns a number and changes status to issued', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const r = issueInvoice(invoice, []);
  assert.equal(r.ok, true);
  const issued = r.value;
  assert.equal(issued.number, 'INV-2025-0001');
  assert.equal(issued.status, 'issued');
  assert.equal(issued.customerId, 'C-001');
  assert.equal(issued.issueDate, '2025-10-15');
});

test('issueInvoice increments the invoice number', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const existing = ['INV-2025-0001', 'INV-2025-0002'];
  const r = issueInvoice(invoice, existing);
  assert.equal(r.ok, true);
  assert.equal(r.value.number, 'INV-2025-0003');
});

test('issueInvoice resets counter for different year', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const existing = ['INV-2025-0001', 'INV-2025-0002', 'INV-2025-0003'];
  const r = issueInvoice(invoice, existing);
  assert.equal(r.ok, true);
  assert.equal(r.value.number, 'INV-2026-0001');
});

test('issueInvoice preserves all invoice fields', () => {
