test('invoiceTotals calculates discount on a single line', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 10, discountPercent: 10 }],
  }).value;
  // Line total: 10 * 8500 = 85000 cents
  // Discount: 85000 * 10 / 100 = 8500 cents
  // Total: 85000 - 8500 = 76500 cents

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 85000);
  assert.equal(totals.discount, 8500);
  assert.equal(totals.total, 76500);
});

test('invoiceTotals sums discounts across multiple lines', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [
      { sku: 'DES-HOUR', qty: 10, discountPercent: 10 },
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 20 },
    ],
  }).value;
  // Line 1: 10 * 8500 = 85000, discount 10% = 8500
  // Line 2: 10 * 9500 = 95000, discount 20% = 19000
  // Total discount: 27500
  // Subtotal: 180000
  // Total: 152500

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 180000);
  assert.equal(totals.discount, 27500);
  assert.equal(totals.total, 152500);
});

test('invoiceTotals handles decimal discounts with rounding', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 3, discountPercent: 12.5 }],
  }).value;
  // Line total: 3 * 8500 = 25500 cents
  // Discount: 25500 * 12.5 / 100 = 3187.5, rounded to 3188
  // Total: 25500 - 3188 = 22312

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 25500);
  assert.equal(totals.discount, 3188);
  assert.equal(totals.total, 22312);
});

