test('issueInvoice assigns a number and changes status to issued', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const r = issueInvoice(invoice, []);
  assert.equal(r.ok, true);
  const issued = r.value;
  assert.equal(issued.number, 'INV-2025-0001');
  assert.equal(issued.status, 'issued');
  assert.equal(issued.customerId, 'C-001');
  assert.equal(issued.issueDate, '2025-10-15');
});

test('issueInvoice increments the invoice number', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const existing = ['INV-2025-0001', 'INV-2025-0002'];
  const r = issueInvoice(invoice, existing);
  assert.equal(r.ok, true);
  assert.equal(r.value.number, 'INV-2025-0003');
});

test('issueInvoice resets counter for different year', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;

  const existing = ['INV-2025-0001', 'INV-2025-0002', 'INV-2025-0003'];
  const r = issueInvoice(invoice, existing);
  assert.equal(r.ok, true);
  assert.equal(r.value.number, 'INV-2026-0001');
});

test('issueInvoice preserves all invoice fields', () => {
  const invoice = createInvoice({
    customerId: 'C-003',
    issueDate: '2025-12-25',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'DEV-HOUR', qty: 10 },
    ],
  }).value;

  const r = issueInvoice(invoice, []);
  assert.equal(r.ok, true);
  const issued = r.value;
  assert.equal(issued.customerId, 'C-003');
  assert.equal(issued.issueDate, '2025-12-25');
  assert.equal(issued.lines.length, 2);
  assert.equal(issued.lines[0].sku, 'DES-HOUR');
  assert.equal(issued.lines[0].qty, 2);
  assert.equal(issued.lines[1].sku, 'DEV-HOUR');
  assert.equal(issued.lines[1].qty, 10);
});

test('issueInvoice refuses to issue a non-draft invoice', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-10-15',
    status: 'sent',
    lines: [
      {
        sku: 'DES-HOUR',
        name: 'Design work (hour)',
        qty: 5,
        unitPrice: 8500,
        vatRate: 21,
      },
    ],
  };

  assert.deepEqual(issueInvoice(invoice, []), { ok: false, error: 'NOT_DRAFT' });
});

test('issueInvoice does not mutate the original invoice', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  }).value;
  const invoiceCopy = JSON.stringify(invoice);

  issueInvoice(invoice, []);
  assert.equal(JSON.stringify(invoice), invoiceCopy);
});
